// No backdrop: nothing is drawn or animated behind the conversation.
const LOOK: ThemeSetArgs = { colors: COLORS }

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // Display only and not restored on resume, so it is set on every start.
    await $.theme.set(LOOK)

    return next(e)
  })
}
